  const state = {
    /** 独立会话窗钉住的会话 id（URL 的 chatId）；非独立窗为空 */
    subWindowPinnedId: '',
    nav: 'singleAi',
    yuYan: 'zh-CN',
    /** 界面显示时区（IANA）；空 = 还没从设置里读回来（生效值回退到系统时区） */
    timezone: '',
    /** 本次启动是否已经排过/弹过"系统时区变了"的提醒（只提醒一次） */
    shiQuTiXingGuo: false,
    t: {},
    selectedChat: null,
    selectedInstance: null,
    urgency: 'P2',
    instances: [],
    groups: [],
    chats: [],
    hardware: null,
    globalSecurity: 'normal',
    sessionSecurity: {},
    /** 聊天框的思考级别覆盖：只对当前聊天对象一次性生效（换会话即失效） */
    thinkOverride: {},
    /** 超出权限是否询问（默认询问；完全授权时该开关灰掉） */
    askOnExceed: true,
    /** 自动选择：默认**不勾**。勾上后，选项卡里标了「推荐」的方案按推荐自动执行 */
    autoSelectRecommended: false,
    /** 定时任务 / 文件产物（右栏卡片的数据） */
    dingShiRenWu: [],
    gongZuoWenJian: [],
    gongZuoQuLuJing: '',
    jiHuaRenWu: [],
    /**
     * 未读数（微信式角标）：**每次新回复 +1**，直到用户点了这个聊天界面里的任何元素才清零
     * （产品要求：即使当前正开着这个会话，角标也要显示）。
     */
    unread: {},
    /** 被打断的任务（程序异常/退出/重启后恢复到的会话）：列表亮 !，会话里给「继续/重试」 */
    planInterrupted: new Set(),
    /** 中断通知先到、但这一轮还在出字 ⇒ 等真正收尾后再点亮按钮（不许半路弹） */
    planInterruptedPending: new Set(),
    /** 中断原因（点「继续/重试」时带给模型分析用） */
    renWuZhongDuan: {},
    /** 对话异常会话（列表角标显示 !） */
    chatErrors: new Set(),
    /** 用户已经看过的异常会话：`!` 角标消失（新异常到来时会被清掉、重新提醒） */
    yiChaKanYiChang: new Set(),
    /** 最近一次决策卡列表缓存（列表角标显示 ?） */
    aiQuestions: [],
    sound: { complete: true, request: true, error: true },
    soundVolume: 0.9,
    autoRead: false,
    /** 项目内文件左键是否用 nm 打开（默认关） */
    nmKaiWenJian: true,
    /** 回复内容加强：牛马按内容自选文字/SVG/图表/交互页/语音讲解（更慢、更费 token） */
    enhanceReply: false,
    /** 加强 AI 语言约束：思考过程与回复严格用界面语言 */
    strictAiLanguage: false,
    soundFiles: { complete: '', request: '', error: '' },
    emailOnRequest: false,
    theme: '#A87654',
    themeMode: 'system',
    consoleOpen: false,
    listSort: 'time',
    /** 置顶会话（id → true）：排在最前，不被新回复顶掉 */
    pinned: {},
    /** 备用快捷键（动作 id → 组合键）：一个动作可同时有两个快捷键 */
    shortcuts2: {},
    smtp: { host: '', port: 465, secure: true, user: '', pass: '' },
    smtpAccounts: [],
    embedUseGpu: true,
    listWidth: 200,
    panelWidth: 300,
    /** 宽屏适配：保存用户设定的栏宽（拖动才标记 yongHu），显示宽度按窗口另行计算 */
    buJuKuan: { lieBiao: 200, mianBan: 300, lieBiaoYongHu: false, mianBanYongHu: false },
    /**
     * R2：用户自己设的快捷键（动作 id → 组合键字符串）。
     * 只存**用户改过的**；没写过的动作走 SHORTCUT_ACTIONS 里的预置值。
     * 空串 = 用户显式解绑（不会回落到预置值）。走既有 settings 通道持久化。
     */
    shortcuts: {},
    attachments: [],
    profile: { loggedIn: false, username: 'nav.touXiang', avatarDataUrl: '', email: '', deviceId: '', avatarPreset: 0 },
    queues: {},
    board: {
      /**
       * ADR：外部聚合看板 — 会话进展只读，点击跳转；值班者写 board.jsonl。
       *
       * ⚠️ 这里**刻意是空的**：以前预置了 4 个演示会话 + 4 条演示动态（demo.project1…），
       * 于是「总看板」在真数据还没来时显示得像"真的有 4 个项目在跑、刚刚完成了任务"
       * （时间戳还是相对现在算的，看着很新）。那属于"看起来在跑其实没跑"。
       * 现在：真数据一律来自 `warmy:kanbanJuHe` / `warmy:kanbanShiJianJi`；
       * 没数据就由 renderDashboard() 如实显示"暂无…"。
       */
      sessions: [],
      /** board.jsonl 结构化事件（值班者解析写入） */
      events: [],
      recent: [],
    },
    chaJianJi: [
      // 产品定稿：只保留 WArmy 自己的记忆系统插件
      // （@nanmicoder/dsh-agent-teams 与 dsh-memory-bundle 是 2026-09-16 UI 面板的默认占位，
      //   从未被任何代码安装/依赖 —— 已删除）
      {
        id: 'warmy-memory',
        ming: 'warmy-memory-system',
        enabled: true,
        desc: 'plugin.warmyMemory.desc',
        source: 'builtin',
      },
      {
        // **内置文件查看器**（可卸载；卸载后由设置→功能里的“安装 nm 查看器”装回）
        id: 'nm-file',
        ming: 'nm文件',
        enabled: true,
        desc: 'plugin.nmFile.desc',
        source: 'builtin',
      },
    ],
    /** 用户主动卸载过 nm 查看器 ⇒ 更新/重启都不许自动装回（设置→功能里可重装） */
    nmFileRemoved: false,
    providers: PROVIDER_DEFAULTS.map((p) => ({ ...p, models: [] })),
    /** 当前**生效**供应商 id（聊天真正用谁）；编辑其它供应商绝不劫持它 */
    activeProviderId: 'deepseek',
  };

  const __CONSOLE_CAP_EARLY = 200;
  /** 设置页当前分区（跨 renderPage 保留，见 bindSettingsMenu） */
  let settingsSection = 'ui';

  /* ── 供应商列表的落盘（设置 → 模型） ────────────────────────────────
   * 事实来源 = 设置文件里的 `providers`；**密钥不在里面**（走 safeStorage）。
   * 这里只做三件事：读回来、写回去、把密钥存在与否问出来（永远读不回明文）。 */
  function providerRecordOf(p) {
    return {
      id: String(p.id || ''),
      biaoQian: String(p.biaoQian || ''),
      protocol: PROVIDER_PROTOCOLS.includes(p.protocol) ? p.protocol : 'openai-compatible',
      baseURL: String(p.baseURL || ''),
      defaultModel: String(p.defaultModel || ''),
      models: Array.isArray(p.models) ? p.models.map((m) => String(m)) : [],
      staleModels: (p.staleModels && typeof p.staleModels === 'object') ? { ...p.staleModels } : {},
      hasKey: !!p.hasKey,
    };
  }
  async function saveProviders() {
    try {
      await window.warmy.settingsSave({
        providers: state.providers.map(providerRecordOf),
        providersSeeded: true,
      });
    } catch { /* 写失败不影响本次界面；下次改动会再试 */ }
  }
  async function loadProvidersFromSettings() {
    let seeded = false;
    try {
      const r = await window.warmy.settingsGet?.();
      const saved = r?.settings?.providers;
      seeded = !!r?.settings?.providersSeeded;
      if (Array.isArray(saved) && (saved.length || seeded)) {
        state.providers = saved.map((p) => providerRecordOf(p));
      } else {
        // 从来没落盘过：用出厂预设初始化一次（之后一律以落盘为准，删光了也不会自己回来）
        state.providers = PROVIDER_DEFAULTS.map((p) => providerRecordOf({ ...p, models: [] }));
        await saveProviders();
      }
    } catch { /* 读不到就用内置预设顶着 */ }
    try {
      const idJi = state.providers.map((p) => p.id);
      const h = await window.warmy.providerKeyHas?.({ providerIds: idJi });
      if (h?.ok) state.providers.forEach((p) => { p.hasKey = !!h.has[p.id]; });
    } catch { /* 问不到就当没有：界面会显示"未设置密钥" */ }
    // 读回**当前生效**供应商 id（编辑其它供应商不得劫持它）
    try {
      const g = await window.warmy.getProvider?.();
      const cur = g && (g.providerCfg || g);
      if (cur && cur.presetId) state.activeProviderId = String(cur.presetId);
    } catch { /* 读不到就保持默认 */ }
    /**
     * **读回已落盘的模型能力**（真事故：能力只在内存，重启后警示图标就没了）。
     * 拉取模型时把 kind/tools/vision/contextLen 存进了 settings.modelCaps，
     * 这里启动时灌回 `window.__moXingNengLi` ⇒ 牛马管理局的能力徽章与警示图标立刻可用。
     */
    try {
      const c = await window.warmy.modelCapsGet?.();
      if (c?.ok && c.caps && typeof c.caps === 'object') {
        window.__moXingNengLi = Object.assign({}, c.caps, window.__moXingNengLi || {});
      }
    } catch { /* 读不到不影响其它功能 */ }
  }
  window.__warmyReloadProviders = loadProvidersFromSettings;
  /**
   * 第 81 轮 #14：**删一个模型 = 从所有模型列表、默认项与调用链里彻底移除**。
   *
   * 真事故：设置→模型里在「模型选项」链上点删除，`renderSmLian` 下一拍又会把这个模型
   * 从供应商 `models` 里「补回链尾」—— 用户看到的是"删掉的模型跑到最底下"。
   * 根因是删除只改了链，没有改模型来源；而渲染层把供应商模型当作事实来源。
   *
   * 所以这里统一做一次全局清理（供应商卡片 ×、特殊模型链的删除都走这里）：
   *   · 供应商 `models` / `defaultModel` / `staleModels`
   *   · 每只牛马的 `availableModels` / `chain` / `chainDisabled` / `defaultModel` / `currentModel` / `model`
   *   · 特殊模型链（通过渲染层注册的 `__shanTeShuMoXingYinYong`，含 manual）
   * 清理后立即落盘；刷新页面/重启后都**不会复活**。
   */
  const moXingMingYiZhi = (entry, mid) => {
    const s = String(entry == null ? '' : entry).trim();
    const m = String(mid == null ? '' : mid).trim();
    if (!s || !m) return false;
    if (s === m) return true;
    // 牛马侧存的是「供应商名 · 模型id」，删除时两种形态都要命中
    return s.endsWith(' · ' + m);
  };
  async function shanChuMoXingQuanJu(modelId) {
    const mid = String(modelId == null ? '' : modelId).trim();
    if (!mid) return false;
    let changed = false;
    for (const p of (state.providers || [])) {
      if (!p) continue;
      const before = Array.isArray(p.models) ? p.models.length : 0;
      p.models = (p.models || []).filter((x) => String(x) !== mid);
      if (p.models.length !== before) changed = true;
      if (String(p.defaultModel || '') === mid) { p.defaultModel = ''; changed = true; }
      if (p.staleModels && Object.prototype.hasOwnProperty.call(p.staleModels, mid)) {
        delete p.staleModels[mid];
        changed = true;
      }
    }
    for (const inst of (state.instances || [])) {
      if (!inst) continue;
      for (const k of ['availableModels', 'chain', 'chainDisabled']) {
        if (!Array.isArray(inst[k])) continue;
        const next = inst[k].filter((x) => !moXingMingYiZhi(x, mid));
        if (next.length !== inst[k].length) { inst[k] = next; changed = true; }
      }
      for (const k of ['defaultModel', 'currentModel', 'model']) {
        if (inst[k] != null && moXingMingYiZhi(inst[k], mid)) {
          if (k === 'currentModel') delete inst.currentModel; else inst[k] = '';
          changed = true;
        }
      }
    }
    try {
      if (typeof window.__shanTeShuMoXingYinYong === 'function') {
        if (window.__shanTeShuMoXingYinYong(mid)) changed = true;
      }
    } catch { /* 特殊链清理失败不挡主流程 */ }
    try { await saveProviders(); } catch { /* 写失败下次改动会再试 */ }
    try { if (changed) window.__saveState?.(); } catch { /* noop */ }
    return changed;
  }
  window.__shanChuMoXingQuanJu = shanChuMoXingQuanJu;
  /**
   * 给**自动化门禁**用的两个钩子（真人从来不点这个）：
   *  · `__warmyRenderPage`：门禁要能"灌一份设置 → 立即按真实渲染路径重画"，
   *    否则只能靠静态文本断言（历史上正是这种弱断言把"没跑过"当成了"过了"）；
   *  · `__warmyProviders`：读回渲染层当前持有的供应商数组（只读快照）。
   */
  window.__warmyRenderPage = () => { renderPage(); try { guaKuaiJieJianTiShi(); } catch { /* noop */ } };
  window.__langDuWenBen = langDuWenBen;

  /** 只读调试快照（门禁/自动诊断用；不改变任何行为） */
  window.__warmyDebugState = () => ({
    nav: state.nav,
    yiGuding: state.subWindowPinnedId || '',
    selected: state.selectedChat ? state.selectedChat.id : null,
    selectedKind: state.selectedChat ? state.selectedChat.kind : null,
    chatWindow: document.body.classList.contains('liaoTianChuangKou'),
    itemCount: document.querySelectorAll('#lieBiaoTi .lieBiaoTiaoMu').length,
  });
  const t = (k) => state.t[k] || k;
  /** t() 缺键时会原样返回键名；界面文案用它拿真正兜底 */
  const tOr = (k, fallback) => {
    const v = state.t[k];
    return (v && v !== k) ? v : fallback;
  };
