          reasoningDuan: (m.reasoningDuan && m.reasoningDuan.length) ? m.reasoningDuan : (l.reasoningDuan || []),
          zhongJian: (m.zhongJian && m.zhongJian.length) ? m.zhongJian : (l.zhongJian || []),
