  function shouLiuShiKuai() {
    try {
      const heZi = $('xiaoXiJi');
      if (!heZi) return;
      /**
       * 停止时**不把流式气泡整块删掉**（用户反馈：「停止后要保留思考的内容（折叠起来），
       * 不是全部隐藏掉」）。行业做法也是这条：Stop 要**保留已产生的部分输出**，只标记为未完成。
       * 这里：保留正文与思考块，把思考块**折叠**起来，并去掉流式标记 + 标一句「已停止」。
       */
      heZi.querySelectorAll('[data-streaming="1"]').forEach((n) => {
        n.removeAttribute('data-streaming');
        n.classList.add('yiTingZhi');
        n.querySelectorAll('.siKaoKuai').forEach((sk) => {
          const wenBen = sk.querySelector('pre');
          // 折叠：正文收起来，留一行可点开的摘要
          if (wenBen) wenBen.classList.add('yinCang');
          if (!sk.querySelector('.siKaoZheDie')) {
            const zhe = document.createElement('div');
            zhe.className = 'siKaoZheDie jingYin';
            zhe.textContent = tOr('chat.thinkingCollapsed', '思考与执行（已折叠 · 点击展开）');
            zhe.onclick = () => {
              if (!wenBen) return;
              const yin = wenBen.classList.toggle('yinCang');
              zhe.textContent = yin
                ? tOr('chat.thinkingCollapsed', '思考与执行（已折叠 · 点击展开）')
                : tOr('chat.thinkingExpanded', '思考与执行（点击收起）');
            };
            sk.insertBefore(zhe, sk.firstChild);
          }
        });
      });
    } catch { /* noop */ }
  }
  window.__shouLiuShiKuai = shouLiuShiKuai;

  /**
   * **这段文字有没有实际内容**（真机反馈修：回复完成后多出一条只有「。」的回复）。
   *
   * 模型偶尔只吐一个标点当作答复；原来只判 `trim()` ⇒ 标点被当成正文 ⇒ 界面多一个空气泡。
   * 这里把"只有标点/空白/零宽字符"一律当**没有内容**，走既有的空回复占位文案。
   * （主进程侧同一套判据见 `youShiZhiWenBen`，两处都拦，任何入口进来的都不显示空话。）
   */
  function youShiZhiWenBen(wen) {
    const s = String(wen || '')
      .replace(/[\s\u200B-\u200F\uFEFF]/g, '')
      .replace(/[.,;:!?'"`~^\-_=+*\\/|<>()[\]{}@#$%&。，、；：！？…·—～「」『』（）【】《》“”‘’]/g, '')
      // 只有 emoji / 装饰符号不算正文（续派那轮只回一个 ✨ 时不再多出一条气泡）
      .replace(/[\u2190-\u21FF\u2300-\u27BF\u2B00-\u2BFF\uFE0F\u3030\u303D\u00A9\u00AE\u2122]/g, '')
      .replace(/[\u{1F000}-\u{1FAFF}]/gu, '')
      .replace(/[\u{1F1E6}-\u{1F1FF}]/gu, '');
    return s.length > 0;
  }
  window.__youShiZhiWenBen = youShiZhiWenBen;

  /**
   * 模型降级的悬停文案（产品要求：放在鼠标悬停时显示的模型后面）。
   * 例：`huihui_ai/qwen3-vl-abliterated:4b （Qwen3.6-35B-A3B-IQ3_M:latest-128K 调用失败，已改用： huihui_ai/qwen3-vl-abliterated:4b）`
   */
  function jiangJiWenBen(j) {
    try {
      if (!j) return '';
      // 产品要求 T5：优先用主进程生成的完整降级文本
      const fuZhu = String(j.fuZhu || '');
      if (fuZhu) return fuZhu;
      const shiBai = Array.isArray(j.shiBai) ? j.shiBai.filter(Boolean) : [];
      const yuanYin = String(j.yuanYin || '').slice(0, 200);
      if (!shiBai.length) return '';
      const A = shiBai.slice(0, 3).join('、') + (shiBai.length > 3 ? '…' : '');
      /**
       * 第 34 轮 项 8：悬停提示里**不再写"已改用：某某"** —— 这一行显示的就是最终在用的模型，
       * 提示里再报一遍等于"（本轮已改用上面那个）"这种废话（产品明确要求删掉）。
       */
      return A + ' ' + tOr('chat.modelDegradedMid', '调用失败') + (yuanYin ? '（' + yuanYin + '）' : '');
    } catch { return ''; }
  }
  /** 降级信息的短展示（放模型名后面括号里，超长省略） */
  function jiangJiDuan(j) {
    const s = jiangJiWenBen(j);
    if (!s) return '';
    return s.length > 40 ? s.slice(0, 40) + '…' : s;
  }

  /**
   * **消息指纹**（赞/踩要能跨重渲染记住是哪一条）：时间戳 + 模型 + 正文前 64 字的简易散列。
   * 不用内容全文做键（太长），也不用下标（会随增删漂）。
   */
  function maoYao(m) {
    const s = String((m && m.ts) || 0) + '|' + String((m && m.moXing) || '') + '|' + String((m && m.text) || '').slice(0, 64);
    let h = 5381;
    for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
    return 'm' + (h >>> 0).toString(36);
  }

  /**
   * **字节数 → 人类可读**（产品要求：超过 1024 就进位，B → KB → MB → GB → TB）。
   *
   * 真事故：附件条与产物卡以前都是 `Number(a.bytes) + 'B'` —— 一张 3.4MB 的图显示成
   * 「3569280B」，又长又看不出量级；而且**只有**走文件选择器加的附件带 `bytes`，
   * 截图 / 图片预览那条路根本没有大小可显示（"照片的大小似乎没有显示"）。
   */
  function renLeiDaXiao(n) {
    const v = Number(n);
    if (!Number.isFinite(v) || v < 0) return '';
    if (v < 1024) return v + ' B';
    const dan = ['KB', 'MB', 'GB', 'TB', 'PB'];
    let x = v / 1024;
    let i = 0;
    while (x >= 1024 && i < dan.length - 1) { x /= 1024; i++; }
    // 1 位小数；整数则去掉小数点（1024B → 1KB，不是 1.0KB）
    const s = x >= 100 ? String(Math.round(x)) : x.toFixed(1).replace(/\.0$/, '');
    return s + ' ' + dan[i];
  }
  /**
   * **补齐附件缺失的字节数**（异步，拿到后重渲染一次）。
   * 覆盖：截图附件、图片预览那条路、以及任何只有 path 没有 bytes 的条目。
   */
  function buQiFuJianDaXiao() {
    (state.attachments || []).forEach((a) => {
      if (!a || a.bytes || !a.path || a.__daXiaoTried) return;
      a.__daXiaoTried = true;
      void (async () => {
        try {
          const r = await window.warmy.wenJianDaXiao?.({ path: a.path });
          if (r && r.ok && Number(r.bytes) >= 0) { a.bytes = Number(r.bytes); xuanranFujian(); }
        } catch { /* 拿不到就不显示大小，不编 */ }
      })();
    });
  }

  /**
   * **按模型标签把模型分配到对应功能链**（拉取模型后自动做）。
   *
   * 产品要求：拉取完模型，设置里那些「听话 / 说话 / 向量 / 看图 / 对话」的选项
   * 要**按标签归位**，不能让用户一个个手挑。规则只**追加**：
   *   · 已经在链里的不重复加；
   *   · 用户排好的顺序不动（新来的接在后面）；
   *   · 禁用名单里的不加。
   *
   * 标签来源是拉取模型时主进程给的能力表（`modelCaps` / `moXingNengLi`：kind + vision）。
   */
  async function anBiaoQianFenPeiMoXing(models, nengLi) {
    const sp = await window.warmy.specialModelsGet?.().catch(() => null);
    const sm = (sp && sp.specialModels) || {};
    /** kind → 链键；chat 特殊（要看 vision） */
    const daoLian = {
      asr: ['asrChain'], tts: ['ttsChain'], embedding: ['embedChain'],
      image: ['imageChain'], ocr: ['ocrChain'], rerank: ['rerankChain'],
      imageUnd: ['imageUndChain'], videoUnd: ['videoUndChain'], videoGen: ['videoGenChain'],
    };
    const tianFenPei = (lianMing, mo) => {
      const lian = Array.isArray(sm[lianMing]) ? sm[lianMing].slice() : [];
      const jin = Array.isArray(sm[lianMing.replace(/Chain$/, 'Disabled')]) ? sm[lianMing.replace(/Chain$/, 'Disabled')] : [];
      if (lian.includes(mo) || jin.includes(mo)) return false;
      lian.push(mo);
      sm[lianMing] = lian;
      return true;
    };
    let gai = false;
    for (const mo of models || []) {
      const nl = (nengLi && nengLi[mo]) || {};
      /**
       * 标签优先用能力表；表里是 unknown 时**按名字兜底**（本轮修：端点元数据常常不给 kind，
       * 于是拉取完一个都没归位）。与 providers 的已知型号表同一套命名规律。
       */
      let kind = String(nl.kind || '').toLowerCase();
      const ming = String(mo || '').toLowerCase();
      if (!kind || kind === 'unknown') {
        // Ollama 上的 whisper 是文本模型（无 /audio/transcriptions）⇒ 不进听话链（真机：dimavz/whisper-tiny 无法转写）
        if (/whisper/.test(ming) && !/whisper.*(server|api|http)/.test(ming)) kind = 'chat';
        else if (/whisper|(^|[-_/])asr([-_/]|$)|(^|[-_/])stt([-_/]|$)|paraformer|sense-?voice/.test(ming)) kind = 'asr';
        else if (/(^|[-_/])tts([-_/]|$)|text-?to-?speech|voice-?clone|cosyvoice|melo-?tts/.test(ming)) kind = 'tts';
        else if (/bge-|embed|gte-|nomic-embed|text-embedding/.test(ming)) kind = 'embedding';
        else if (/rerank/.test(ming)) kind = 'rerank';
        else if (/stable-diffusion|sdxl|flux|text-?to-?image/.test(ming)) kind = 'image';
        else if (/whisper-vision|(^|[-_/])ocr([-_/]|$)/.test(ming)) kind = 'ocr';
        else kind = 'chat';
      }
      const vision = nl.vision === true || /(-vl-|vision|llava|qwen.*-vl|multimodal)/i.test(ming);
      const muBiao = daoLian[kind] || [];
      for (const l of muBiao) if (tianFenPei(l, mo)) gai = true;
      if (kind === 'chat' || !kind) {
        if (vision) { if (tianFenPei('imageUndChain', mo)) gai = true; }
        if (tianFenPei('chatChain', mo)) gai = true;
        if (tianFenPei('organizerChain', mo)) gai = true;
      }
    }
    if (gai) {
      await window.warmy.specialModelsSet?.(sm);
      /** 归位后**立刻刷新链 UI**（否则界面上还显示空的 —— 真机反馈） */
      try { await window.__fillSpecialModelSelects?.(); } catch { /* 刷新失败不影响归位 */ }
    }
    return gai;
  }
  /** 供验证脚本直接调（拉取模型后按标签归位那一步） */
  window.__anBiaoQianFenPeiMoXing = anBiaoQianFenPeiMoXing;

