        j.className = 'jianTou';
        j.textContent = '⌄';
        j.style.marginLeft = 'auto';
        biaoTi.appendChild(j);
        biaoTi.classList.add('daKai');
        /** 补出来的箭头要接进 toggle：以前 `jianTou` 是 const 且在补之前取值 ⇒ 折叠时箭头永远不动 */
        jianTou = j;
