    const want = panCardsFor(panCardKindKey());
    if (!Array.isArray(want) || !want.length) return;
    const kaPian = [...host.querySelectorAll(PAN_KA_SEL)];
    if (kaPian.length < 2) return;
    const rank = new Map(want.map((id, i) => [id, i]));
