    const sel = state.selectedChat;
    const shiDai = ++yunXingShiDai;
    const current = () => yunXingShiDai === shiDai && state.selectedChat === sel
      && String(state.selectedChat.id) === sid && state.sessionRuns[sid] === run && !run.running;
