            $('smtpXiaoXi').textContent = t('common.loading');
            const vr = await window.warmy.smtpVerify({ ...Quan, id });
            $('smtpXiaoXi').textContent = vr?.ok ? t('smtp.ok') : t('smtp.fail') + ': ' + (vr?.message || '');
            renderSmtpList();
