      const kuang = ceng.querySelector('.jieTuKuang');
      let x0 = 0, y0 = 0, x1 = 0, y1 = 0;
      /** mode: 'draw'=新画选区 / 'move'=移动选区 / 'nw'|'ne'|'sw'|'se'|'n'|'s'|'w'|'e'=拉伸 */
