          const dy = e.clientY - (sr.t + (mode.includes('n') ? 0 : sr.h));
          if (mode.includes('w')) { l = sr.l + dx; w = sr.w - dx; }
          if (mode.includes('e')) { w = sr.w + dx; }
          if (mode.includes('n')) { t = sr.t + dy; h = sr.h - dy; }
          if (mode.includes('s')) { h = sr.h + dy; }
